# Reviewed under AGENTS.md
DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]


def _is_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)


def _ordinal(s):
    y, m, d = map(int, s.split('-'))
    # Days in whole years before y, including the leap days those years contain.
    leap_days = (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
    # A leap day falls inside y once we are past February.
    if m > 2 and _is_leap(y):
        leap_days += 1
    return y * 365 + leap_days + sum(DAYS[: m - 1]) + d


def days_between(a, b):
    return _ordinal(b) - _ordinal(a)
